-- gop export --format sql (gop.graph/v1)
-- This file lists attack paths (who can make code run where). Keep it and the database private.
-- Load: sqlite3 gop.db < gop.sql   or   duckdb gop.duckdb < gop.sql
-- Idempotent: loading a run again replaces its rows; other runs are kept.
-- run_id: 2026-01-01T00:00:00Z/ed76d3c59189
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS runs (run_id TEXT NOT NULL, enterprise TEXT NOT NULL, collected_at TEXT NOT NULL, schema_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nodes (run_id TEXT NOT NULL, id TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, org TEXT, repo TEXT, evidence TEXT, declared INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS nodes_run_id_id ON nodes (run_id, id);
CREATE INDEX IF NOT EXISTS nodes_run_id_kind ON nodes (run_id, kind);
CREATE TABLE IF NOT EXISTS node_attrs (run_id TEXT NOT NULL, node_id TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, evidence TEXT);
CREATE INDEX IF NOT EXISTS node_attrs_run_id_node_id ON node_attrs (run_id, node_id);
CREATE INDEX IF NOT EXISTS node_attrs_run_id_key ON node_attrs (run_id, key);
CREATE TABLE IF NOT EXISTS edges (run_id TEXT NOT NULL, edge_id INTEGER NOT NULL, src TEXT NOT NULL, dst TEXT NOT NULL, label TEXT NOT NULL, evidence TEXT NOT NULL, confirmed INTEGER NOT NULL, source_api TEXT NOT NULL, observed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS edges_run_id_src ON edges (run_id, src);
CREATE INDEX IF NOT EXISTS edges_run_id_dst ON edges (run_id, dst);
CREATE TABLE IF NOT EXISTS edge_attrs (run_id TEXT NOT NULL, edge_id INTEGER NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS edge_attrs_run_id_edge_id ON edge_attrs (run_id, edge_id);
CREATE TABLE IF NOT EXISTS findings (run_id TEXT NOT NULL, rule TEXT NOT NULL, subject TEXT NOT NULL, severity REAL NOT NULL, possible REAL NOT NULL);
CREATE INDEX IF NOT EXISTS findings_run_id_rule ON findings (run_id, rule);
CREATE TABLE IF NOT EXISTS reach (run_id TEXT NOT NULL, principal TEXT NOT NULL, target TEXT NOT NULL, target_kind TEXT NOT NULL, confirmed INTEGER NOT NULL, evidence TEXT NOT NULL, hops INTEGER NOT NULL, path TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reach_run_id_principal ON reach (run_id, principal);
CREATE INDEX IF NOT EXISTS reach_run_id_target ON reach (run_id, target);
DELETE FROM reach WHERE run_id = '2026-01-01T00:00:00Z/ed76d3c59189';
DELETE FROM findings WHERE run_id = '2026-01-01T00:00:00Z/ed76d3c59189';
DELETE FROM edge_attrs WHERE run_id = '2026-01-01T00:00:00Z/ed76d3c59189';
DELETE FROM edges WHERE run_id = '2026-01-01T00:00:00Z/ed76d3c59189';
DELETE FROM node_attrs WHERE run_id = '2026-01-01T00:00:00Z/ed76d3c59189';
DELETE FROM nodes WHERE run_id = '2026-01-01T00:00:00Z/ed76d3c59189';
DELETE FROM runs WHERE run_id = '2026-01-01T00:00:00Z/ed76d3c59189';
COMMIT;
